const openLoans = `-- name: OpenLoans :many
SELECT id, employee_id, loan_type, principal_amount, interest_rate, tenor_months, monthly_installment, remaining_balance, paid_amount, first_installment_month, first_installment_year, status, is_active, purpose, approved_by, approved_at, rejected_by, rejected_at, rejection_reason, created_by, created_at, updated_at FROM hr.loans
WHERE employee_id = $1 AND status = 'approved' AND is_active AND remaining_balance > 0
ORDER BY approved_at NULLS LAST, created_at
`

func (q *Queries) OpenLoans(ctx context.Context, employeeID string) ([]HrLoan, error) {
	rows, err := q.db.Query(ctx, openLoans, employeeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HrLoan{}
	for rows.Next() {
		var i HrLoan
		if err := rows.Scan(
			&i.ID,
			&i.EmployeeID,
			&i.LoanType,
			&i.PrincipalAmount,
			&i.InterestRate,
			&i.TenorMonths,
			&i.MonthlyInstallment,
			&i.RemainingBalance,
			&i.PaidAmount,
			&i.FirstInstallmentMonth,
			&i.FirstInstallmentYear,
			&i.Status,
			&i.IsActive,
			&i.Purpose,
			&i.ApprovedBy,
			&i.ApprovedAt,
			&i.RejectedBy,
			&i.RejectedAt,
			&i.RejectionReason,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

